  // ----- the Baron's Night (boss_say lines are the Baron's speech bubbles: shown, never spoken as words) -----
  s_boss: ['Baron von Shiny', 'Барон фон Блеск', 'Barone von Luccichio'],
  boss_intro: ['Let\'s spoil Baron von Shiny\'s silly plan, Chief!', 'Давай сорвём смешной план Барона фон Блеска, командир!',
    'Fermiamo il piano buffo del Barone von Luccichio, Capo!'],
  boss_ask1: ['A giant cake? Check it first, Chief!', 'Огромный торт? Сначала проверь, командир!', 'Una torta gigante? Prima controlla, Capo!'],
  boss_tip1: ['Real cakes have no feet, Chief!', 'У настоящих тортов нет лап, командир!', 'Le torte vere non hanno le zampe, Capo!'],
  boss_ask2: ['Tap the parcels with magpies inside!', 'Нажми на посылки, где прячутся сороки!', 'Tocca i pacchi con le gazze dentro!'],
  boss_tip2: ['A heart tag means a gift from a friend!', 'Сердечко на бирке — это подарок от друга!', 'Cartellino col cuore? È il regalo di un amico!'],
  boss_ask3: ['Which lock is the strongest, Chief?', 'Какой замочек самый крепкий, командир?', 'Qual è il lucchetto più forte, Capo?'],
  boss_tip3: ['More pictures make a stronger lock!', 'Чем больше картинок, тем крепче замочек!', 'Più figure ci sono, più il lucchetto è forte!'],
  boss_win: ['The Baron\'s whole plan fell apart, Chief!', 'Весь план Барона развалился, командир!', 'Il piano del Barone è andato in pezzi, Capo!'],
  boss_say1: ['A cake for you! No need to check!', 'Торт для вас! Проверять не нужно!', 'Una torta per voi! Niente controlli!'],
  boss_say2: ['Presents for you! Take them all inside!', 'Подарки для вас! Несите их все в домик!', 'Regali per voi! Portateli tutti dentro!'],
  boss_say3: ['My Guess-o-Matic opens any lock!', 'Мой Угадай-о-мат откроет любой замок!', 'Il mio Indovinomatic apre ogni lucchetto!'],
  boss_say4: ['Curses! Until next time!', 'Ах, досада! До новой встречи!', 'Accidenti! Alla prossima!'],
